package com.bank.wfpath.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Unique Paths with a single rolling row updated left to right.
public class WorkflowPathService {
    private static final Logger log = Logger.getLogger(WorkflowPathService.class.getName());

    public long countApprovalRoutes(int stages, int departments) {
        long[] dp = new long[departments];                 // one cell per department column
        Arrays.fill(dp, 1L);                               // top row: exactly one route each
        for (int i = 1; i < stages; i++) {
            for (int j = 1; j < departments; j++) {
                dp[j] += dp[j - 1];                         // from above (dp[j]) + from left (dp[j-1])
            }
        }
        final long result = dp[departments - 1];
        log.info(() -> "Distinct approval routes = " + result);
        return dp[departments - 1];
    }
}
